const input = $input.first().json;
const triggerData = $('Execute Workflow Trigger').first().json;

let enhancedPrompt = triggerData.prompt;
let negativePrompt = '';

try {
  const geminiResponse = input.candidates?.[0]?.content?.parts?.[0]?.text;
  if (geminiResponse) {
    const parsed = JSON.parse(geminiResponse);
    enhancedPrompt = parsed.enhanced_prompt || enhancedPrompt;
    negativePrompt = parsed.negative_prompt || '';
  }
} catch (e) {
  // fallback to original prompt
}

return [{
  json: {
    prompt: enhancedPrompt,
    negative_prompt: negativePrompt,
    original_prompt: triggerData.prompt,
    type: triggerData.type || 'social_post',
    dimensions: triggerData.dimensions || '1080x1080',
    context: triggerData.context || '',
    for_workflow: triggerData.for_workflow || 'manual'
  }
}];

const response = $input.first().json;
const promptData = $('Parse — Prompt enrichi').first().json;

let imageBase64 = null;
let mimeType = 'image/png';

try {
  const parts = response.candidates?.[0]?.content?.parts || [];
  for (const part of parts) {
    if (part.inlineData) {
      imageBase64 = part.inlineData.data;
      mimeType = part.inlineData.mimeType || 'image/png';
      break;
    }
  }
} catch (e) {
  throw new Error('Erreur parsing réponse Gemini Imagen: ' + e.message);
}

if (!imageBase64) {
  throw new Error('Aucune image générée par Gemini Imagen. Vérifiez que le modèle supporte la génération d\'images.');
}

const extension = mimeType.includes('png') ? 'png' : mimeType.includes('jpeg') ? 'jpg' : 'png';
const timestamp = new Date().toISOString().replace(/[:.]/g, '-');
const filename = `maxmorrys-${promptData.type}-${timestamp}.${extension}`;

return [{
  json: {
    filename,
    mimeType,
    imageBase64,
    type: promptData.type,
    dimensions: promptData.dimensions,
    original_prompt: promptData.original_prompt,
    enhanced_prompt: promptData.prompt,
    for_workflow: promptData.for_workflow,
    context: promptData.context,
    generated_at: new Date().toISOString()
  }
}];

