const uploadResponse = $input.first().json;
const imageData = $('Parse — Extraire l\'image').first().json;

let driveUrl = '';
let driveFileId = '';

try {
  driveFileId = uploadResponse.id || '';
  driveUrl = driveFileId ? `https://drive.google.com/uc?id=${driveFileId}` : '';
} catch (e) {
  // upload may have failed, continue with base64
}

return [{
  json: {
    success: !!driveFileId,
    file_id: driveFileId,
    file_url: driveUrl,
    filename: imageData.filename,
    type: imageData.type,
    dimensions: imageData.dimensions,
    original_prompt: imageData.original_prompt,
    enhanced_prompt: imageData.enhanced_prompt,
    for_workflow: imageData.for_workflow,
    context: imageData.context,
    generated_at: imageData.generated_at
  }
}];
